"""Write release notes and metadata only after the shared checks pass."""
from pathlib import Path
import json,subprocess
R=Path(__file__).resolve().parents[1]
def read(n):return json.loads((R/n).read_text())
def main():
 data=read('validation_0229/data_results.json');runtime=read('validation_0229/runtime_results.json');assert data['passed']and runtime['passed']
 w=read('data/world.json');audit=read('data/map_edit_audit_0229.json');old=read('tools/cartography/edits_0229/baseline/world.json');ps=read('data/provinces.json')
 total=sum(s['population']for s in w['regions'].values());commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=R,text=True).strip()
 info={'version':'0.2.0.29','baseline_version':'0.2.0.28','repository_base_commit':commit,'engine':'Godot 4.5.1 stable official','countries':len(w['countries']),'states':len(w['regions']),'land_provinces':len(ps),'sea_regions':len(read('data/sea_regions.json')),'population':total,'geography_version':'0.2.0.29','display_version':'0.2.0.29','scenario_id':w['scenario_id'],'source_update':True,'windows_executable_exported':False,'native_windows_tested':False,'fresh_campaign_required':True,'map_data_changed':True,'simulation_changed':False,'changes':['User colour-map edits applied; state pixels take priority','Existing province IDs fitted to states; detached scraps and new narrow fragments absorbed by bordering tiles','Only fully painted-out Istanbul Province 7 and Maracaibo province removed; cities retained','Sea borders, adjacency, selection fields and picking source rebuilt from current sea IDs','Year-2000 resident/demographic/workforce totals conserved across modeled edited-boundary transfers'],'validation':{'data':data,'runtime':runtime,'native_windows_tested':False}}
 (R/'BUILD_INFO.json').write_text(json.dumps(info,indent=2)+'\n')
 lines=['# BunnyWorld 0.2.0.29 — edited-map integration','','Changed-files patch over **0.2.0.28**. **224 countries, 1,261 states, 13,198 land provinces and 120 sea regions**. No new province IDs. World population remains **6,146,495,066**.','','## Applied rules','','- The uploaded `newsts.zip` maps are the approved geometry. All edited state pixels and sea pixels are preserved exactly.','- State borders override competing province shapes. Existing province colours/IDs are fitted inside the edited states.','- Detached inland pieces and small new fitting slivers are absorbed into bordering provinces of the same state. Real separate islands may share a province.','- Only two fully erased IDs are removed: **10465 — Istanbul · Province 7**, and **12585 — Maracaibo**. Maracaibo city and its buildings/scenery remain; the city now links to province 12597.','- All 2,340 city records, 2,787 scenery clusters and 8 landmarks remain, at their original coordinates. Fourteen city province links changed.','- This uploaded edit set did not change the land/water silhouette. The Åland correction changes state membership of existing land, rather than adding or removing coastline. Antarctic terrain is unchanged.','- Provinces remain movement/building tiles with no resident population. Global simulation and live offscreen owner changes remain independent of map visibility.','','## Bookkeeping','','Population moved between states is an **educated estimate** proportional to the source state’s transferred land area. This is not a fresh local census or an urban-density estimate. Residents are never created or discarded. Single-age profiles, religious categories, adult-25 education counts and workforce counts are carried with the source residents using exact integer allocation. Global counts are conserved; country totals change only where the painted border transfers land between controllers. All unaffected demographic profiles are unchanged. Buildings and building slots retain their accepted state inventories.','','### Country population changes','','| Country/controller | Before | After | Change |','|---|---:|---:|---:|']
 for tag,c in audit['country_population_changes'].items():lines.append(f"| {w['countries'][tag]['name']} | {c['before']:,} | {c['after']:,} | {c['after']-c['before']:+,} |")
 lines+=['','## Fitted states','','Province counts are preserved in each state except the two explicit removals; no province changed state ID. Pixel-level fitting stays within the approved state geometry.','','| State | Provinces before → after | Population before → after | Fitted pixels | Fragment/sliver pixels absorbed |','|---|---:|---:|---:|---:|']
 for row in audit['repairs']:
  sid=str(row['state']);s=w['regions'][sid];o=old['regions'][sid];lines.append(f"| {s['name']} ({sid}) | {len(o['provinces'])} → {len(s['provinces'])} | {o['population']:,} → {s['population']:,} | {row['fitted_pixels']} | {row['fragment_sliver_pixels']} |")
 lines+=['','## Rebuilt together','','Current categorical PNGs, province index, province/state adjacency, province/state border meshes, sea border mesh and neighbours, spatial render batches, shared boundary fields, coast fields/windows, tiny-island coverage, sea selection fields, GPU sea mask and versioned/checksummed restore bundles. The shared pipeline now registers sea-ID edits instead of reusing old sea selection geometry.','','## Validation','',f"**{data['checks']:,} data checks** and **{runtime['checks']:,} Godot 4.5.1 headless checks**, zero failures. Includes exact uploaded state/sea pixels; retained province IDs; 4-connected province fragments on all fitted state landmasses; references/capitals; city and scenery preservation; exact global demographic/workforce conservation; every province interior picking anchor; all 120 sea anchors and selection uploads; map modes; save/load; and offscreen ownership updates without geometry rebuilding.",'','Headless validation does **not** establish Windows visual quality or FPS. The previously reported close-zoom border-rendering artifacts and broader city-province generation refinements still need their own investigation.','','## Apply and test','','1. Close Godot and the game. Back up the working .28 folder.','2. Extract the patch over .28, replacing included files. Run **Prepare_BunnyWorld.bat**; all reported versions must be **0.2.0.29**.','3. Open with **Godot 4.5.1 Standard**, allow imports to finish and start a **fresh campaign**.','4. Check Åland/southwest Finland, Brussels, the edited Egyptian/Afghan borders and Timor. Select states and provinces on both sides.','5. Check your city-province edits, especially Chicago/Tokyo/Yokohama and Maracaibo; confirm the city remains after its tile merger.','6. Check sea borders and highlights in the Baltic, North Sea, Canadian Arctic, Japan/Okhotsk and Indonesia.','7. Change an offscreen state owner with the existing console, return to it and verify the colour/owner.','8. Try physical and political modes at several zoom levels. Compare close-zoom border artifacts separately; this patch does not claim to fix them.','9. Save/load within .29. Old-version saves are unsupported.','','No Windows EXE is included. Use the existing Windows export instructions. `PATCH_REMOVED_FILES_0229.txt` lists obsolete prepared asset parts; unreferenced old parts are harmless if retained.','','## Reproducibility','','`tools/cartography/edits_0229/tile_*.npz` and `sea.npz` retain the exact decoded old/new editing maps. `baseline/` and `runtime_before.json` retain the .28 data used for bookkeeping. Starting from the recorded .28 commit, restore prepared assets, copy the included decoded inputs/baseline capture, run `tools/apply_edits_0229.py`, then `tools/build_map.py --godot <Godot 4.5.1>` and the .29 tests. Run the baseline capture only before editing. `data/map_edit_audit_0229.json` records transfers, fitting, removals and exact expected demographic counts.']
 (R/'documentation/MAP_EDITS_0229.md').write_text('\n'.join(lines)+'\n')
 (R/'README.md').write_text(f'''# Bunny World 0.2.0.29

User map edits integrated over **0.2.0.28**: **224 countries, 1,261 states, 13,198 land provinces, 120 sea regions**. State borders take priority; province IDs are preserved except two fully erased tiles. All cities remain. Sea borders, neighbours and highlights rebuild from current IDs. Population is state-only.

## Apply and run

1. Back up .28 and close Godot/game.
2. Extract the changed-files ZIP beside project.godot, replacing included files.
3. Run **Prepare_BunnyWorld.bat**; application/geography/display must all report **0.2.0.29**.
4. Open with **Godot 4.5.1 Standard**, allow imports and start a **fresh campaign**.

{data['checks']:,} data checks and {runtime['checks']:,} Godot headless checks pass. See [report and test order](documentation/MAP_EDITS_0229.md). Native Windows visuals/performance remain the user test. No EXE is included; see [export instructions](documentation/EXPORT_WINDOWS.md).

Controls: right-drag rotate; wheel zoom; left click inspect; Space pause; 1–4 speed; Ctrl+F search; F focus; F5/F9 same-version save/load; F11 fullscreen; Escape menu.
''')
 (R/'TEST_RESULTS.md').write_text(f"# BunnyWorld 0.2.0.29 verification\n\n{data['checks']:,} data checks and {runtime['checks']:,} Godot 4.5.1 headless checks pass, zero failures. See validation_0229 and documentation/MAP_EDITS_0229.md. Native Windows visuals/performance are untested.\n")
 print('RELEASE_0229_DOCUMENTED',flush=True)
if __name__=='__main__':main()
